# ---------------------------------------------------------
# Recall@K
# ---------------------------------------------------------

def calculate_recall_at_k(
    retrieved_results: list[list[dict]],
    relevant_ids: list[set],
    k: int = 5
) -> float:

    if not retrieved_results:
        return 0.0

    hits = 0

    for results, relevant in zip(
        retrieved_results,
        relevant_ids
    ):

        top_k = results[:k]

        retrieved_ids = {
            result["chunk_id"]
            for result in top_k
        }

        # Did we retrieve at least one relevant chunk?
        if retrieved_ids.intersection(relevant):
            hits += 1

    return hits / len(retrieved_results)


# ---------------------------------------------------------
# Mean Reciprocal Rank
# ---------------------------------------------------------

def calculate_mrr(
    retrieved_results: list[list[dict]],
    relevant_ids: list[set]
) -> float:

    if not retrieved_results:
        return 0.0

    reciprocal_ranks = []

    for results, relevant in zip(
        retrieved_results,
        relevant_ids
    ):

        reciprocal_rank = 0.0

        for rank, result in enumerate(
            results,
            start=1
        ):

            if result["chunk_id"] in relevant:

                reciprocal_rank = 1 / rank
                break

        reciprocal_ranks.append(
            reciprocal_rank
        )

    return sum(reciprocal_ranks) / len(
        reciprocal_ranks
    )

def judge_answer(
    question: str,
    context: str,
    generated_answer: str,
) -> dict:

    judge_prompt = f"""
You are evaluating an answer produced by a RAG system.

Question:
{question}

Retrieved Context:
{context}

Generated Answer:
{generated_answer}

Evaluate the generated answer using ONLY the retrieved context.

Return ONLY valid JSON in this exact format:

{{
    "correct": true,
    "grounded": true,
    "relevant": true,
    "reason": "short explanation"
}}

Definitions:

- correct:
  The answer gives the correct information for the question.

- grounded:
  Every factual claim in the answer is supported by the retrieved context.

- relevant:
  The answer directly addresses the question without unnecessary information.

Use true or false only for the three boolean fields.
Do not add markdown.
Do not add any text outside the JSON.
"""

    response = call_llm(
        prompt=judge_prompt,
        max_tokens=300,
        system="You are a strict RAG evaluation judge.",
    )

    raw_result = response["text"].strip()

    try:
        return json.loads(raw_result)

    except json.JSONDecodeError:

        print("Warning: Judge returned invalid JSON:")
        print(raw_result)

        return {
            "correct": False,
            "grounded": False,
            "relevant": False,
            "reason": "Judge returned invalid JSON.",
        }

# ---------------------------------------------------------
# Evaluate retrieval
# ---------------------------------------------------------

def evaluate_retrieval(
    chunks,
    bm25_index,
    test_cases: list[dict] = RETRIEVAL_TEST_CASES,
    k: int = 5
) -> dict:

    retrieved_results = []
    relevant_ids = []

    print("\n========== RETRIEVAL EVALUATION ==========\n")

    for test in test_cases:

        question = test["question"]

        print(f"Question: {question}")

        # Run multi-query hybrid retrieval
        results = multi_query_hybrid_search(
            query=question,
            chunks=chunks,
            bm25_index=bm25_index,
            top_k=k,
        )

        retrieved_results.append(results)

        relevant_ids.append(
            set(test["relevant_chunk_ids"])
        )

        # Show retrieved chunks
        print("Retrieved:")

        for rank, result in enumerate(
            results[:k],
            start=1
        ):

            print(
                f"  {rank}. "
                f"{result.get('chunk_id', 'unknown')} "
                f"| score={result.get('score', 0):.4f}"
            )

        print()

    # Calculate metrics
    recall = calculate_recall_at_k(
        retrieved_results,
        relevant_ids,
        k=k
    )

    mrr = calculate_mrr(
        retrieved_results,
        relevant_ids
    )

    print("------------------------------------------")
    print(f"Recall@{k}: {recall:.4f}")
    print(f"MRR:        {mrr:.4f}")
    print("------------------------------------------")

    return {
        "recall_at_k": recall,
        "mrr": mrr,
        "k": k,
        "num_test_cases": len(test_cases),
    }
def evaluate_answers(
    chunks,
    bm25_index,
    test_cases=RETRIEVAL_TEST_CASES,
):
    print("\n========== ANSWER EVALUATION ==========\n")

    correct_count = 0
    grounded_count = 0
    relevant_count = 0

    total = len(test_cases)

    for test in test_cases:

        question = test["question"]

        print(f"Question: {question}")

        # 1. Retrieve
        hybrid_results = multi_query_hybrid_search(
            query=question,
            chunks=chunks,
            bm25_index=bm25_index,
            top_k=CONFIG.retrieval_k,
        )

        # 2. Rerank
        reranked_results = rerank(
            query=question,
            candidates=hybrid_results,
            top_k=CONFIG.rerank_k,
        )

        # 3. Context filtering
        filtered_results = filter_context(
            reranked_results
        )

        # 4. Generate answer
        answer = generate_answer(
            query=question,
            reranked_results=filtered_results,
        )

        generated_answer = answer["answer"]

        print("\nGenerated answer:")
        print(generated_answer)

        print("\nExpected answer:")
        print(test["expected_answer"])

        # 5. Build context
        context = "\n".join(
            result["text"]
            for result in filtered_results
        )

        # 6. LLM Judge
        judge_result = judge_answer(
            question=question,
            context=context,
            generated_answer=generated_answer,
        )

        print("\nLLM Judge:")
        print(json.dumps(
            judge_result,
            indent=4
        ))

        # 7. Count metrics

        if judge_result["correct"]:
            correct_count += 1

        if judge_result["grounded"]:
            grounded_count += 1

        if judge_result["relevant"]:
            relevant_count += 1

        print("\nResult:")

        print(
            f"Correct    : "
            f"{'PASS' if judge_result['correct'] else 'FAIL'}"
        )

        print(
            f"Grounded   : "
            f"{'PASS' if judge_result['grounded'] else 'FAIL'}"
        )

        print(
            f"Relevant   : "
            f"{'PASS' if judge_result['relevant'] else 'FAIL'}"
        )

        print("------------------------------------------")

    # 8. Calculate metrics

    correctness = (
        correct_count / total
        if total > 0
        else 0.0
    )

    groundedness = (
        grounded_count / total
        if total > 0
        else 0.0
    )

    relevance = (
        relevant_count / total
        if total > 0
        else 0.0
    )

    print("\n========== EVALUATION SUMMARY ==========\n")

    print(
        f"Correctness  : {correctness:.4f}"
    )

    print(
        f"Groundedness : {groundedness:.4f}"
    )

    print(
        f"Relevance    : {relevance:.4f}"
    )

    print("\n=========================================\n")

    return {
        "correctness": correctness,
        "groundedness": groundedness,
        "relevance": relevance,
        "total": total,
    }
if __name__ == "__main__":
    from app.pipeline import prepare_pipeline

    chunks, bm25_index = prepare_pipeline()

    evaluate_retrieval(
        chunks=chunks,
        bm25_index=bm25_index,
    )

    evaluate_answers(
        chunks=chunks,
        bm25_index=bm25_index,
    )